    98	    visibility: "org",
    99	    leadId: owner.id,
   100	    color: "#6366f1",
   101	    targetDate: null,
   102	  });
   103	
   104	  return {
   105	    org,
   106	    project,
   107	    actors: actors as Readonly<Record<Role, Actor>>,
   108	    userIds: userIds as Readonly<Record<Role, UserId>>,
   109	  };
   110	}
