    59	  return {
    60	    id: ORG_A,
...
   150	    orgId: ORG_A,
   151	    userId: user.id,
   152	    role: "member",
   153	    status: "active",
   154	    invitedBy: null,
   155	    joinedAt: EPOCH,
   156	    lastSeenAt: EPOCH,
   157	    archivedAt: null,
   158	    createdAt: EPOCH,
   159	    updatedAt: EPOCH,
   160	    ...overrides,
   161	    user,
   162	  };
   163	}
   164	
   165	export function makeLimitCheck(overrides: Partial<LimitCheck> = {}): LimitCheck {
   166	  const limit = overrides.limit ?? 3;
   167	  const used = overrides.used ?? 1;
   168	  return {
   169	    resource: "seats",
   170	    plan: "free",
   171	    limit,
   172	    used,
   173	    remaining: Math.max(0, limit - used),
   174	    exceeded: used >= limit,
   175	    ...overrides,
   176	  };
   177	}

