"use client";

/**
 * Removal confirmation.
 */
import { Button } from "@/components/ui/button";
import { Dialog, DialogFooter } from "@/components/ui/dialog";
import { isBillableRole, type MemberWithUser } from "@/types/member";
import type { ReactElement } from "react";
import { RoleBadge } from "../permission/role-badge";

export type RemoveMemberDialogProps = {
  open: boolean;
  member: MemberWithUser;
  onConfirm: () => void;
  onClose: () => void;
};

export function RemoveMemberDialog(
  props: RemoveMemberDialogProps,
): ReactElement | null {
  const { open, member, onConfirm, onClose } = props;
  if (!open) return null;

  return (
    <Dialog
      open={open}
      title={`Remove ${member.user.name}?`}
      description="They lose access immediately. Issues and comments they authored stay, attributed to them."
      onClose={onClose}
      footer={
        <DialogFooter>
          <Button variant="secondary" onClick={onClose}>
            Cancel
          </Button>
          <Button variant="danger" onClick={onConfirm}>
            Remove member
          </Button>
        </DialogFooter>
      }
    >
      <p className="text-sm">
        {member.user.email} is currently a <RoleBadge role={member.role} /> in
        this organization. Removing them frees one seat.
      </p>
    </Dialog>
  );
}

/**
 * Pending invitations.
 *
 * Owner D. Read-only listing plus revoke. `InvitationService` exposes the
 * lifecycle verbs but no listing, so the page reads
 * `listPendingInvitations()` from the repository directly — the query is
 * already org-scoped and there is no rule for a service to add on top of it.
 *
 * Must call (do not reimplement): can
 */

import { notFound } from "next/navigation";
import type { Metadata } from "next";
import { PENDING_MEMBER_ID } from "@/actions/_lib/permission-resources";
import { InvitationList } from "@/components/domain/member/invitation-list";
import { EmptyState } from "@/components/ui/empty-state";
import { can } from "@/lib/permissions";
import { listPendingInvitations } from "@/server/repositories/invitation-repository";
import { revokeInvitation } from "@/server/services/invitation-service";
import type { InvitationId } from "@/types/common";
import { loadTenantContext } from "../../../_lib/tenant-context";

type PageParams = { orgSlug: string };

export const dynamic = "force-dynamic";

export const metadata: Metadata = {
  title: "Pending invitations",
};

export default async function Page(props: {
  params: Promise<PageParams>;
  searchParams: Promise<Record<string, string | string[] | undefined>>;
}) {
  // Next.js 16: params and searchParams are Promises and MUST be awaited.
  const { orgSlug } = await props.params;
  await props.searchParams;

  const { org, actor } = await loadTenantContext(orgSlug);

  const mayRead = can(actor, "member:read", {
    kind: "member",
    orgId: org.id,
    memberId: PENDING_MEMBER_ID,
    targetUserId: actor.userId,
    targetRole: actor.role,
  });
  if (!mayRead) {
    notFound();
  }

  const invitations = await listPendingInvitations(org.id);

  async function revoke(invitationId: InvitationId): Promise<void> {
    "use server";
    await revokeInvitation(actor, invitationId);
  }

  return (
    <div className="space-y-8">
      <header>
        <h1 className="text-xl font-semibold tracking-tight">
          Pending invitations
        </h1>
        <p className="mt-1 text-sm text-slate-600">
          Invitations that have been sent but not yet accepted. Each one still
          counts against the seat quota.
        </p>
      </header>

      {invitations.length === 0 ? (
        <EmptyState
          title="No invitations outstanding"
          description="Everybody who was invited has either joined or been revoked."
        />
      ) : (
        <InvitationList
          invitations={invitations}
          actor={actor}
          onRevoke={revoke}
        />
      )}
    </div>
  );
}

/**
 * Invitation landing page; accepts or explains an expired token.
 *
 * Owner D. Dynamic, because whether the visitor already has a session decides
 * what they are shown: signed in, they get an accept button; signed out, they
 * are sent to the sign-in form with the invite as the destination.
 *
 * The token itself is never resolved here — `InvitationService` is the only
 * thing that may look one up, and only when it is being consumed.
 */

import Link from "next/link";
import { redirect } from "next/navigation";
import type { Metadata } from "next";
import { getSessionPrincipal } from "@/lib/session";
import { invitationTokenSchema } from "@/schemas/invitation";
import { InviteAcceptForm } from "./invite-accept-form";

type PageParams = { token: string };

export const dynamic = "force-dynamic";

export const metadata: Metadata = {
  title: "You have been invited",
};

export default async function Page(props: {
  params: Promise<PageParams>;
  searchParams: Promise<Record<string, string | string[] | undefined>>;
}) {
  // Next.js 16: params and searchParams are Promises and MUST be awaited.
  const { token } = await props.params;
  const search = await props.searchParams;

  const parsed = invitationTokenSchema.safeParse(token);
  if (!parsed.success) {
    return (
      <div className="space-y-3">
        <h1 className="text-lg font-semibold">This invitation is not valid</h1>
        <p className="text-sm text-slate-600">
          The link may have been truncated by an email client, or the invitation
          may have been revoked. Ask whoever invited you to send a new one.
        </p>
        <Link href="/login" className="text-sm text-indigo-600">
          Go to sign in
        </Link>
      </div>
    );
  }

  const principal = await getSessionPrincipal();
  if (principal === null) {
    redirect(`/login?next=${encodeURIComponent(`/invite/${token}`)}`);
  }

  const orgSlug = typeof search.org === "string" ? search.org : null;

  return (
    <div className="space-y-5">
      <div className="space-y-2">
        <h1 className="text-lg font-semibold">You have been invited</h1>
        <p className="text-sm text-slate-600">
          Accepting adds {principal.email} to the organization and takes up one
          of its seats.
        </p>
      </div>

      <InviteAcceptForm token={parsed.data} orgSlug={orgSlug} />
    </div>
  );
}

