        memberId: member.id,
        role: "admin",
      }),
    ).resolves.toMatchObject({ role: "admin" });

    await expect(
      memberService.updateMemberRole(full.actors.owner, {
        orgId: full.org.id,
        memberId: member.id,
        role: "viewer",
      }),
    ).resolves.toMatchObject({ role: "viewer" });
  });
});

describe("BillingService.checkLimit", () => {
  it("reports the plan, the usage and whether one more would breach", async () => {
    await usageService.recomputeUsage(free.org.id);

    const check = await billingService.checkLimit(free.org.id, "seats");

    expect(check).toMatchObject({
      resource: "seats",
      plan: "free",
      limit: 3,
      used: 3,
      remaining: 0,
      exceeded: true,
    });
  });

  it("leaves an org with room under its limit", async () => {
    await usageService.recomputeUsage(growth.org.id);

    const check = await billingService.checkLimit(growth.org.id, "seats");
    expect(check.exceeded).toBe(false);
    expect(check.remaining).toBeGreaterThan(0);
  });
});

/**
 * Plan-limit enforcement on the write paths.
 *
 * `PLAN_LIMITS` is the single source of the numbers and `wouldExceedLimit()`
 * the single comparison; these cases prove the services actually consult them
 * before writing, and that a pending invitation already holds its seat.
 */
import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/logger", async () => (await import("./_support/doubles/misc")).loggerModule);
// The only double left in this suite. `@/lib/rate-limit` is real everywhere
// else, but these cases need to *choose* the verdict — the seat-quota refusal
// has to be provably about seats and not about a bucket the previous case
// happened to drain, and the throttling case needs a guaranteed denial.
vi.mock("@/lib/rate-limit", async () => (await import("./_support/doubles/misc")).rateLimitModule);

import { getPlanLimits } from "@/config/plan-limits";
import * as invitationRepo from "@/server/repositories/invitation-repository";
import * as memberRepo from "@/server/repositories/member-repository";
import * as userRepo from "@/server/repositories/user-repository";
import * as billingService from "@/server/services/billing-service";
import * as invitationService from "@/server/services/invitation-service";
import * as memberService from "@/server/services/member-service";
import * as projectService from "@/server/services/project-service";
import * as usageService from "@/server/services/usage-service";
import { rateLimitState } from "./_support/doubles/misc";
import { createTenant, useTemporaryDatabase } from "./_support/fixtures";
import type { Tenant } from "./_support/fixtures";
import type { Role } from "@/types/member";

let cleanup: () => void;

/** Adds `count` active members in `role` straight through the repositories. */
async function seedMembers(tenant: Tenant, count: number, role: Role): Promise<void> {
  for (let i = 0; i < count; i += 1) {
    const user = await userRepo.insertUser({
      email: `${role}-${i}@${tenant.org.slug}.test`,
      name: `${role} ${i}`,
      passwordHash: "seed",
    });
    await memberRepo.insertMember(tenant.org.id, user.id, role, null);
  }
}
/** Free plan: 3 seats, 2 projects. The fixture seeds three billable members and a viewer. */
let free: Tenant;
let growth: Tenant;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  free = await createTenant("frugal", "free");
  growth = await createTenant("growing", "growth");
});

afterAll(() => {
  cleanup();
  rateLimitState.allowed = true;
});

describe("seat quota on invite", () => {
  it("rejects an invite once the plan's seats are taken", async () => {
    expect(getPlanLimits("free").seats).toBe(3);
    await expect(memberRepo.countActiveMembers(free.org.id)).resolves.toBe(3);

    await expect(
      invitationService.inviteMember(free.actors.owner, {
        orgId: free.org.id,
        email: "fifth@frugal.test",
        role: "member",
      }),
    ).rejects.toThrow(/seats/i);
  });

  it("writes no invitation row when the quota rejects the batch", async () => {
    await expect(
      invitationRepo.countPendingInvitations(free.org.id),
    ).resolves.toBe(0);
  });

  it("rejects a bulk invite as a whole rather than partially filling it", async () => {
    const limits = getPlanLimits("growth");
    expect(limits.seats).toBe(50);

    const invites = Array.from({ length: 49 }, (_, index) => ({
      email: `bulk-${index}@growing.test`,
      role: "member" as const,
    }));

    await expect(
      invitationService.inviteMembers(growth.actors.owner, {
        orgId: growth.org.id,
        invites,
      }),
    ).rejects.toThrow(/seats/i);

    await expect(
      invitationRepo.countPendingInvitations(growth.org.id),
    ).resolves.toBe(0);
  });

  it("counts a pending invitation against the seat quota", async () => {
    const before = await invitationRepo.countPendingInvitations(growth.org.id);

    await invitationService.inviteMember(growth.actors.owner, {
      orgId: growth.org.id,
      email: "solo@growing.test",
      role: "member",
    });

    await expect(
      invitationRepo.countPendingInvitations(growth.org.id),
    ).resolves.toBe(before + 1);
  });

  it("refuses the invite when the rate limiter says no", async () => {
    rateLimitState.allowed = false;

    await expect(
      invitationService.inviteMember(growth.actors.owner, {
        orgId: growth.org.id,
        email: "throttled@growing.test",
        role: "member",
      }),
    ).rejects.toThrow(/rate limit/i);

    rateLimitState.allowed = true;
  });
});

describe("project quota", () => {
  it("rejects the project that would exceed the plan", async () => {
    expect(getPlanLimits("free").projects).toBe(2);

    // The fixture already created one project; this fills the plan.
    await projectService.createProject(free.actors.owner, {
      orgId: free.org.id,
      name: "Second",
      slug: "second",
      key: "SEC",
      description: null,
      visibility: "org",
      leadId: null,
      color: "#6366f1",
      targetDate: null,
    });

    await expect(
      projectService.createProject(free.actors.owner, {
        orgId: free.org.id,
        name: "Third",
        slug: "third",
        key: "THR",
        description: null,
        visibility: "org",
        leadId: null,
        color: "#6366f1",
        targetDate: null,
      }),
    ).rejects.toThrow(/projects/i);
  });
});

describe("viewers are free", () => {
  it("accepts a batch of viewer invites even when the plan is already full", async () => {
    const full = await createTenant("viewer-batch", "free");

    const invitations = await invitationService.inviteMembers(full.actors.admin, {
      orgId: full.org.id,
      invites: [
        { email: "watch-a@viewer-batch.test", role: "viewer" },
        { email: "watch-b@viewer-batch.test", role: "viewer" },
      ],
    });

    expect(invitations).toHaveLength(2);
  });

  it("counts only the billable invites in a mixed batch", async () => {
    const tenant = await createTenant("viewer-mixed", "starter");
    await seedMembers(tenant.org.id, 6, "member");

    // 9 of 10 seats are taken: one billable invite fits alongside any viewers.
    await expect(
      invitationService.inviteMembers(tenant.actors.admin, {
        orgId: tenant.org.id,
        invites: [
          { email: "mix-a@viewer-mixed.test", role: "member" },
          { email: "mix-b@viewer-mixed.test", role: "viewer" },
          { email: "mix-c@viewer-mixed.test", role: "viewer" },
        ],
      }),
    ).resolves.toHaveLength(3);

    // A second billable invite has no seat left, so the whole batch is refused.
    await expect(
      invitationService.inviteMembers(tenant.actors.admin, {
        orgId: tenant.org.id,
        invites: [
          { email: "mix-d@viewer-mixed.test", role: "member" },
          { email: "mix-e@viewer-mixed.test", role: "viewer" },
        ],
      }),
    ).rejects.toThrow(/seats/);
  });

  it("refuses a viewer becoming billable when no seat is left, and changes nothing", async () => {
    const full = await createTenant("viewer-promote", "free");
    const viewer = await memberRepo.findMember(full.org.id, full.userIds.viewer);
    if (!viewer) throw new Error("fixture viewer missing");

    await expect(
      memberService.updateMemberRole(full.actors.owner, {
        orgId: full.org.id,
        memberId: viewer.id,
        role: "member",
      }),
    ).rejects.toThrow(/seats/);

    await expect(
      memberRepo.findMemberById(full.org.id, viewer.id),
    ).resolves.toMatchObject({ role: "viewer" });
  });

  it("lets a viewer become billable once a seat is free", async () => {
    const tenant = await createTenant("viewer-promote-room", "growth");
    const viewer = await memberRepo.findMember(tenant.org.id, tenant.userIds.viewer);
    if (!viewer) throw new Error("fixture viewer missing");

    const promoted = await memberService.updateMemberRole(tenant.actors.owner, {
      orgId: tenant.org.id,
      memberId: viewer.id,
      role: "member",
    });

    expect(promoted.role).toBe("member");
  });

  it("never refuses a role change that does not take a seat, even on a full plan", async () => {
    const full = await createTenant("viewer-free-moves", "free");
    const member = await memberRepo.findMember(full.org.id, full.userIds.member);
    if (!member) throw new Error("fixture member missing");

    // Billable to billable, and billable to viewer, both leave the seat count alone.
    await expect(
      memberService.updateMemberRole(full.actors.owner, {
        orgId: full.org.id,
        memberId: member.id,
        role: "admin",
      }),
    ).resolves.toMatchObject({ role: "admin" });

    await expect(
      memberService.updateMemberRole(full.actors.owner, {
        orgId: full.org.id,
        memberId: member.id,
        role: "viewer",
      }),
    ).resolves.toMatchObject({ role: "viewer" });
  });
});

describe("BillingService.checkLimit", () => {
  it("reports the plan, the usage and whether one more would breach", async () => {
    await usageService.recomputeUsage(free.org.id);

    const check = await billingService.checkLimit(free.org.id, "seats");

    expect(check).toMatchObject({
      resource: "seats",
      plan: "free",
      limit: 3,
      used: 3,
      remaining: 0,
      exceeded: true,
    });
  });

  it("leaves an org with room under its limit", async () => {
    await usageService.recomputeUsage(growth.org.id);

    const check = await billingService.checkLimit(growth.org.id, "seats");
    expect(check.exceeded).toBe(false);
    expect(check.remaining).toBeGreaterThan(0);
  });
});

